import { describe, expect, it } from "vitest";
import { existsSync, readFileSync } from "node:fs";
import { buildFeatures, featureDim } from "./features";

// Generated by scripts/export_static.py from real extracted clips (git-ignored: derived WLASL data).
const path = "src/static/__fixtures__/parity.json";
const fixture = existsSync(path) ? JSON.parse(readFileSync(path, "utf8")) : null;

describe.skipIf(!fixture)("TypeScript features match Python", () => {
  it("reproduces backend features for real clips", () => {
    const cfg = fixture.feature_config;
    for (const c of fixture.cases) {
      const x = buildFeatures(c.frames, c.width, c.height, cfg);
      const D = featureDim(cfg);
      expect(x.length).toBe(cfg.seq_len * D);
      let max = 0;
      c.features.forEach((row: number[], i: number) => row.forEach((v, k) => { max = Math.max(max, Math.abs(v - x[i * D + k])); }));
      expect(max).toBeLessThan(1e-3);
    }
  });
});
